// Parse format: NODE_1,SOIL:65,HALL:1,MAG:0,TIP:12,TILT:26.91,RAIN:44.04,TEMP:28.5,HUM:75.2,ALERT:0,RSSI:-65,SNR:8.5
var raw = msg.payload;

try {
    var parts = raw.split(',');
    if (parts.length < 6) {
        node.warn('Format data tidak valid: ' + raw);
        return null;
    }

    var data = {
        node: parts[0].trim()
    };

    // Parse key:value pairs
    for (var i = 1; i < parts.length; i++) {
        var kv = parts[i].split(':');
        if (kv.length === 2) {
            var key = kv[0].trim().toLowerCase();
            var val = kv[1].trim();

            if (key === 'soil' || key === 'hall' || key === 'mag' || key === 'tip' || key === 'rssi' || key === 'alert') {
                data[key] = parseInt(val) || 0;
            } else if (key === 'tilt' || key === 'rain' || key === 'snr' || key === 'temp' || key === 'hum') {
                data[key] = parseFloat(val) || 0;
            }
        }
    }

    // Tambahkan timestamp
    data.timestamp = new Date().toISOString();

    // Pastikan semua field ada (termasuk field baru)
    data.soil = data.soil || 0;
    data.hall = data.hall || 0;
    data.mag = data.mag || 0;
    data.tip = data.tip || 0;
    data.tilt = data.tilt || 0;
    data.rain = data.rain || 0;
    data.rssi = data.rssi || 0;
    data.snr = data.snr || 0;
    data.temp = data.temp || 0;
    data.hum = data.hum || 0;
    data.alert = data.alert || 0;

    msg.payload = data;
    return msg;

} catch (e) {
    node.error('Error parsing: ' + e.message);
    return null;
}

// Migrasi kolom baru untuk tabel yang sudah ada
// ALTER TABLE tidak error jika kolom sudah ada (SQLite)
var migrations = [
    "ALTER TABLE sensor_data ADD COLUMN temp REAL DEFAULT 0",
    "ALTER TABLE sensor_data ADD COLUMN hum REAL DEFAULT 0",
    "ALTER TABLE sensor_data ADD COLUMN alert INTEGER DEFAULT 0"
];

// Kirim satu per satu (SQLite tidak support multi-statement)
var msgs = migrations.map(function(sql) {
    return { topic: sql };
});

return [msgs];

var data = msg.payload;
var nodeId = data.node;
var tilt = data.tilt;
var THRESHOLD = 45;  // Derajat
var COOLDOWN_MS = 5 * 60 * 1000;  // 5 menit

// Cek apakah melebihi threshold
if (tilt >= THRESHOLD) {
    // Cek cooldown per node
    var lastAlert = flow.get('lastAlert_' + nodeId) || 0;
    var now = Date.now();

    if (now - lastAlert > COOLDOWN_MS) {
        // Update waktu terakhir alert
        flow.set('lastAlert_' + nodeId, now);

        // Buat pesan Telegram
        var waktu = new Date().toLocaleString('id-ID', {
            timeZone: 'Asia/Jakarta',
            day: '2-digit',
            month: '2-digit',
            year: 'numeric',
            hour: '2-digit',
            minute: '2-digit',
            second: '2-digit'
        });

        var sirenStatus = data.alert ? '🔴 AKTIF' : '⚪ TIDAK AKTIF';

        var pesan = '🚨 *EWS ALERT - BAHAYA LONGSOR* 🚨\n\n'
            + '⚠️ Kemiringan tanah mencapai *' + tilt.toFixed(2) + '°*!\n\n'
            + '📍 *Lokasi:* ' + nodeId.replace('_', ' ') + '\n'
            + '🔺 *Kemiringan:* ' + tilt.toFixed(2) + '°\n'
            + '💧 *Kelembapan Tanah:* ' + data.soil + '%\n'
            + '🌡️ *Suhu Udara:* ' + data.temp.toFixed(1) + '°C\n'
            + '💨 *Kelembapan Udara:* ' + data.hum.toFixed(1) + '%\n'
            + '🌧️ *Curah Hujan:* ' + data.tip + ' tip (' + (data.tip * 3.67).toFixed(1) + ' ml)\n'
            + '📶 *RSSI:* ' + data.rssi + ' dBm\n'
            + '🔊 *Sirene:* ' + sirenStatus + '\n'
            + '⏰ *Waktu:* ' + waktu + '\n\n'
            + '⚠️ Segera lakukan evakuasi jika diperlukan!';

        msg.payload = {
            chatId: '',  // ⚠️ ISI DENGAN CHAT ID TELEGRAM ANDA
            type: 'message',
            content: pesan,
            options: {
                parse_mode: 'Markdown'
            }
        };

        node.status({fill: 'red', shape: 'dot', text: 'Alert ' + nodeId + ' @ ' + tilt.toFixed(1) + '° | Siren: ' + sirenStatus});
        return msg;
    } else {
        // Cooldown aktif
        var sisaCooldown = Math.ceil((COOLDOWN_MS - (now - lastAlert)) / 1000);
        node.status({fill: 'yellow', shape: 'ring', text: 'Cooldown ' + nodeId + ': ' + sisaCooldown + 's'});
        return null;
    }
}

// Normal - tidak kirim
var tempInfo = data.temp ? ' | ' + data.temp.toFixed(1) + '°C' : '';
node.status({fill: 'green', shape: 'dot', text: nodeId + ': ' + tilt.toFixed(1) + '° (Normal)' + tempInfo});
return null;

var hours = msg.req.query.hours || 24;
var nodeFilter = msg.req.query.node || '';

var sql = 'SELECT * FROM sensor_data WHERE timestamp >= datetime("now", "-' + hours + ' hours")';

if (nodeFilter) {
    sql += " AND node = '" + nodeFilter + "'";
}

sql += ' ORDER BY timestamp ASC LIMIT 2000';
msg.topic = sql;
return msg;

var data = msg.payload || [];

msg.payload = {
    success: true,
    count: data.length,
    data: data
};

msg.headers = {
    'Content-Type': 'application/json',
    'Access-Control-Allow-Origin': '*'
